// Calcule le dernier jour ouvré (lundi-vendredi) strictement avant le 8 octobre de l'année en cours.
// Ne tient compte que des week-ends, pas des jours fériés — à vérifier manuellement si un jour férié tombe juste avant.
const now = new Date();
const year = now.getFullYear();
const oct8 = new Date(Date.UTC(year, 9, 8));

let target = new Date(oct8);
target.setUTCDate(target.getUTCDate() - 1);
while (target.getUTCDay() === 0 || target.getUTCDay() === 6) {
  target.setUTCDate(target.getUTCDate() - 1);
}

const targetStr = target.toISOString().slice(0, 10);
const todayStr = now.toISOString().slice(0, 10);

if (todayStr === targetStr) {
  return [{ json: { envoyer: true, date_cible: targetStr, annee: year } }];
}

return [];
